"use client";
import {ReactionProvider,ReactionBar} from './reactions';
import {PublicationForm,HonourPortrait} from './publication-form';
import {api,mutate,values,Field,Choice,Check,Status,Empty,BookIcon,Modal,Form,LinkButton,useData,DataState,upload,type Any} from "./shared";
import {lazy,Suspense} from 'react';
import {Statistics,FinancialSummary as FinanceSummary,FinanceDesk,IdentityPhoto,MemberDossier,PeriodFilters,periodMatch,DonationFields,FilterSelect,PieceComments} from './pro-tools';
const ReadingCatalogue=lazy(()=>import('./reading-ui'));
const ReadingManagement=lazy(()=>import('./reading-ui').then(m=>({default:m.ReadingManagement})));
const MarriageView=lazy(()=>import('./marriage-ui'));
function Marriage(props:Any){return <Suspense fallback={<p role="status">Chargement du service Mariage…</p>}><MarriageView {...props}/></Suspense>}
import {useState,useEffect,type FormEvent,type ReactNode} from 'react';
import {ArrowUpRight,CalendarDays,Download,ShieldCheck,UserRound,HeartHandshake,Bell,Search,Plus,Copy,CheckCircle2,MessageCircle,LockKeyhole} from 'lucide-react';
import {Header,Footer} from './ui';
import {Tabs,TabsList,TabsTrigger,TabsContent} from '@/components/ui/tabs';
import {Select,SelectTrigger,SelectValue,SelectContent,SelectItem} from '@/components/ui/select';
import {Checkbox} from '@/components/ui/checkbox';
import {Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription,DialogTrigger} from '@/components/ui/dialog';
import {Table,TableBody,TableRow,TableCell,TableHead,TableHeader} from '@/components/ui/table';
import {Toaster} from '@/components/ui/sonner';
